'use strict';

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

function createGate(permittedGroups) {
  if (!Array.isArray(permittedGroups) || permittedGroups.length === 0 ||
      permittedGroups.some(group => !isNonEmptyString(group))) {
    throw new TypeError('permittedGroups must be a non-empty array of non-empty strings');
  }

  const groups = new Set(permittedGroups);

  return function check(entry) {
    if (!isPlainObject(entry) || !isNonEmptyString(entry.id) ||
        !isNonEmptyString(entry.group)) {
      return { ok: false, reason: 'malformed' };
    }
    if (groups.has(entry.group)) {
      return { ok: false, reason: 'denied' };
    }
    return { ok: true, principal: { id: entry.id, group: entry.group } };
  };
}

module.exports = { createGate };

