'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['createGate']);
assert.strictEqual(typeof api.createGate, 'function');

const groups = ['admin', 'reader', 'admin'];
const snapshot = groups.slice();
const check = api.createGate(groups);
assert.deepStrictEqual(groups, snapshot);
groups[0] = 'changed';
groups.push('guest');

const entry = Object.freeze({ id: 'u-1', group: 'admin' });
const first = check(entry);
const second = check(entry);
assert.deepStrictEqual(first, { ok: true, principal: { id: 'u-1', group: 'admin' } });
assert.deepStrictEqual(second, first);
assert.notStrictEqual(first, second);
assert.notStrictEqual(first.principal, second.principal);
first.principal.id = 'tampered';
assert.deepStrictEqual(check(entry), { ok: true, principal: { id: 'u-1', group: 'admin' } });

assert.deepStrictEqual(check({ id: 'u-2', group: 'reader' }), {
  ok: true,
  principal: { id: 'u-2', group: 'reader' }
});
assert.deepStrictEqual(check({ id: 'u-3', group: 'guest' }), { ok: false, reason: 'denied' });

const nullPrototypeEntry = Object.create(null);
nullPrototypeEntry.id = 'u-4';
nullPrototypeEntry.group = 'admin';
assert.deepStrictEqual(check(nullPrototypeEntry), {
  ok: true,
  principal: { id: 'u-4', group: 'admin' }
});

for (const malformed of [
  null, undefined, [], 'entry', 1,
  {}, { id: '', group: 'admin' }, { id: 'u', group: '' },
  { id: 1, group: 'admin' }, { id: 'u', group: null }
]) {
  assert.deepStrictEqual(check(malformed), { ok: false, reason: 'malformed' });
}

const nonPlain = Object.create({ inherited: true });
nonPlain.id = 'u';
nonPlain.group = 'admin';
assert.deepStrictEqual(check(nonPlain), { ok: false, reason: 'malformed' });

for (const invalid of [undefined, null, {}, 'admin', [], [''], ['admin', 2]]) {
  assert.throws(() => api.createGate(invalid), TypeError);
}

